export class RendererModuleHost {
    renderer;
    reportDiagnostic;
    states = new Map();
    disposed = false;
    constructor(renderer, reportDiagnostic = () => undefined) {
        this.renderer = renderer;
        this.reportDiagnostic = reportDiagnostic;
    }
    async installAll(modules) {
        this.assertAlive();
        const ordered = orderModules(modules);
        try {
            for (const module of ordered)
                await this.install(module);
        }
        catch (error) {
            await this.disposeAsync();
            throw error;
        }
    }
    async install(module) {
        this.assertAlive();
        if (!module.id.trim())
            throw new Error('Renderer module id cannot be empty.');
        if (this.states.has(module.id))
            throw new Error(`Renderer module is already installed: ${module.id}`);
        for (const dependency of module.requires ?? []) {
            if (!this.states.has(dependency))
                throw new Error(`Renderer module ${module.id} requires ${dependency}.`);
        }
        const cleanups = [];
        const registerCleanup = (cleanup) => {
            cleanups.push(cleanup);
            let registered = true;
            return () => {
                if (!registered)
                    return;
                registered = false;
                const index = cleanups.indexOf(cleanup);
                if (index >= 0)
                    cleanups.splice(index, 1);
            };
        };
        let instance = {};
        try {
            instance = (await module.setup({
                renderer: this.renderer,
                diagnostics: { report: diagnostic => this.reportDiagnostic(diagnostic) },
                registerCleanup,
            })) ?? {};
        }
        catch (error) {
            await runCleanups(cleanups);
            throw error;
        }
        this.states.set(module.id, { module, instance, cleanups });
        return async () => this.uninstall(module.id);
    }
    update(frame) {
        if (this.disposed)
            return;
        for (const state of this.states.values())
            state.instance.update?.(frame);
    }
    beforeRender(scene, camera) {
        if (this.disposed)
            return;
        for (const state of this.states.values())
            state.instance.beforeRender?.(scene, camera);
    }
    afterRender(scene, camera) {
        if (this.disposed)
            return;
        for (const state of [...this.states.values()].reverse())
            state.instance.afterRender?.(scene, camera);
    }
    async recover(context) {
        this.assertAlive();
        for (const state of this.states.values())
            await state.instance.recover?.(context);
    }
    has(id) { return this.states.has(id); }
    get capabilities() {
        return Object.freeze(Object.fromEntries([...this.states].map(([id, state]) => [id, Object.freeze({ ...(state.instance.capabilities ?? {}) })])));
    }
    list() {
        return [...this.states.values()].map(state => Object.freeze({
            id: state.module.id,
            ...(state.module.version ? { version: state.module.version } : {}),
            capabilities: Object.freeze({ ...(state.instance.capabilities ?? {}) }),
        }));
    }
    async uninstall(id) {
        const state = this.states.get(id);
        if (!state)
            return;
        const dependents = [...this.states.values()].filter(value => value.module.requires?.includes(id));
        if (dependents.length > 0)
            throw new Error(`Cannot uninstall renderer module ${id}; required by ${dependents.map(value => value.module.id).join(', ')}.`);
        this.states.delete(id);
        await state.instance.dispose?.();
        await runCleanups(state.cleanups);
    }
    async disposeAsync() {
        if (this.disposed)
            return;
        this.disposed = true;
        const states = [...this.states.values()].reverse();
        this.states.clear();
        for (const state of states) {
            try {
                await state.instance.dispose?.();
            }
            finally {
                await runCleanups(state.cleanups);
            }
        }
    }
    assertAlive() {
        if (this.disposed)
            throw new Error('RendererModuleHost is disposed.');
    }
}
function orderModules(modules) {
    const byId = new Map();
    for (const module of modules) {
        if (byId.has(module.id))
            throw new Error(`Duplicate renderer module id: ${module.id}`);
        byId.set(module.id, module);
    }
    const visiting = new Set();
    const visited = new Set();
    const ordered = [];
    const visit = (id, path) => {
        if (visited.has(id))
            return;
        if (visiting.has(id))
            throw new Error(`Renderer module dependency cycle: ${[...path, id].join(' -> ')}`);
        const module = byId.get(id);
        if (!module)
            throw new Error(`Renderer module dependency is missing: ${id}`);
        visiting.add(id);
        for (const dependency of module.requires ?? [])
            visit(dependency, [...path, id]);
        visiting.delete(id);
        visited.add(id);
        ordered.push(module);
    };
    for (const module of modules)
        visit(module.id, []);
    return ordered;
}
async function runCleanups(cleanups) {
    for (const cleanup of cleanups.splice(0).reverse())
        await cleanup();
}